#include <stdio.h>

#define MAX_SUM 1000005

static int count[MAX_SUM];

int main() {
    int n;
    int s;
    if (scanf("%d %d", &n, &s) != 2) return 0;

    count[0] = 1;
    int current_sum = 0;
    long long ans = 0;

    for (int i = 0; i < n; i++) {
        int x;
        scanf("%d", &x);
        current_sum += x;
        if (current_sum >= s) {
            ans += count[current_sum - s];
        }
        count[current_sum]++;
    }

    printf("%lld\n", ans);

    return 0;
}
